using System;using System.Collections.Generic;using System.Numerics;
namespace SoulboundLegends.NetworkTransport;
public enum ReplicationKind:byte{Player,Npc,Monster,Projectile,WorldEvent,InteractiveObject,Destruction,Item,Vehicle,Custom}
public readonly struct ReplicationEntity{public readonly ulong Id;public readonly ReplicationKind Kind;public readonly ulong InstanceId;public readonly Vector3 Position;public readonly byte Priority;public ReplicationEntity(ulong id,ReplicationKind k,ulong instance,Vector3 pos,byte priority){Id=id;Kind=k;InstanceId=instance;Position=pos;Priority=priority;}}
public interface IAoiProvider{IReadOnlyCollection<ulong> GetRelevantEntities(ulong viewerId,int maxEntities);bool IsVisible(ulong viewerId,ulong entityId);}
public interface IInstanceContextProvider{ulong GetCurrentInstance(ulong connectionId);bool SameInstance(ulong a,ulong b);}
public interface IReplicationStateProvider{IEnumerable<ReplicationEntity> GetEntities(ulong instanceId);byte[] SerializeSpawn(ReplicationEntity e);byte[] SerializeUpdate(ReplicationEntity e);byte[] SerializeDespawn(ulong entityId);}
public sealed class ReplicationScheduler{readonly IAoiProvider aoi;readonly IInstanceContextProvider instances;readonly IReplicationStateProvider state;readonly int max;readonly Dictionary<ulong,HashSet<ulong>> known=new();public ReplicationScheduler(IAoiProvider a,IInstanceContextProvider i,IReplicationStateProvider s,int maxEntities=35){aoi=a;instances=i;state=s;max=maxEntities;}public IEnumerable<(NetworkMessageType type,byte[] payload)> Build(ulong viewer){var set=known.TryGetValue(viewer,out var k)?k:(known[viewer]=new());var relevant=new HashSet<ulong>(aoi.GetRelevantEntities(viewer,max));foreach(var id in relevant){if(!aoi.IsVisible(viewer,id))continue;if(!set.Contains(id)){set.Add(id);yield return(NetworkMessageType.Spawn,state.SerializeSpawn(Find(id,instances.GetCurrentInstance(viewer))));}else yield return(NetworkMessageType.Snapshot,state.SerializeUpdate(Find(id,instances.GetCurrentInstance(viewer))));}foreach(var old in new List<ulong>(set))if(!relevant.Contains(old)){set.Remove(old);yield return(NetworkMessageType.Despawn,state.SerializeDespawn(old));}ReplicationEntity Find(ulong id,ulong instance){foreach(var e in state.GetEntities(instance))if(e.Id==id&&instances.SameInstance(viewer,instance))return e;throw new InvalidOperationException("Replication entity missing");}}}
